using System;namespace Recovered.Gameplay {public static class PtlMaterialServices {public static uint Program(SoundSetupImage m,uint index){return index<=400?unchecked(m.Word(0x297cc6c)+index*0x4d8+4):0;}public static uint Release(SoundSetupImage m,uint program){m.Word(unchecked(program+4),unchecked(m.Word(unchecked(program+4))-1));return program;}public static uint FirstMode(SoundSetupImage m,uint receiver){return (m.Byte(unchecked(receiver+0x654))&0x20)!=0?16u:0u;}public static uint SecondMode(SoundSetupImage m,uint receiver){return (m.Byte(unchecked(receiver+0x654))&0x20)!=0?1u:0u;}public static uint DefaultProgram(SoundSetupImage m,uint runtime,uint material,Func<SoundSetupImage,uint,uint[],uint> call){return call(m,0x7416a0,new uint[]{m.Word(0x297cc6c),runtime,material,0,0,0});}public static uint ModeProgram(SoundSetupImage m,uint runtime,uint material,uint mode,Func<SoundSetupImage,uint,uint[],uint> call){return call(m,0x7416a0,new uint[]{m.Word(0x297cc6c),runtime,material,mode,0,0});}public static void Enter(SoundSetupImage m,Func<SoundSetupImage,uint,uint[],uint> call){call(m,0x4ffaa0,new uint[]{m.Word(0x297ae20)});}public static void Exit(SoundSetupImage m,Func<SoundSetupImage,uint,uint[],uint> call){call(m,0x4ffac0,new uint[]{m.Word(0x297ae20)});}public static uint Invoke(SoundSetupImage m,uint address,uint[] args,Func<SoundSetupImage,uint,uint[],uint> external){if(address==0x741620)return Program(m,args[0]);if(address==0x7415b0)return Release(m,args[0]);if(address==0x6e27d0)return FirstMode(m,args[0]);if(address==0x6e27f0)return SecondMode(m,args[0]);if(address==0x741770)return DefaultProgram(m,args[0],args[1],external);if(address==0x741790)return ModeProgram(m,args[0],args[1],args[2],external);if(address==0x6df300){Enter(m,external);return 0;}if(address==0x6df310){Exit(m,external);return 0;}return external(m,address,args);}public static void Refresh(SoundSetupImage m,uint material,Func<SoundSetupImage,uint,uint[],uint> external){PtlMaterialRefresh.Refresh(m,material,delegate(SoundSetupImage image,uint address,uint[] args){return Invoke(image,address,args,external);});}}}
